'use strict';

const v28TransferStyle=document.createElement('style');
v28TransferStyle.textContent=`
.transfer-result-modal{position:fixed;z-index:80;inset:0;display:grid;place-items:center;padding:18px;background:#071012d9;backdrop-filter:blur(4px)}.transfer-result-card{width:min(580px,100%);max-height:calc(100vh - 36px);overflow:auto;padding:22px;border:1px solid #53696b;border-radius:13px;background:#17282c;box-shadow:0 25px 80px #000d}.transfer-result-head{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;padding-bottom:15px;border-bottom:1px solid #34494c}.transfer-result-head h2{font:700 31px/1 'Barlow Condensed',Impact,sans-serif}.transfer-result-close{width:38px;height:38px;border:1px solid #53676a;border-radius:50%;background:#102126;color:#edf5f0;font-size:24px}.transfer-result-list{display:grid;gap:9px;margin:16px 0}.transfer-result-player{display:grid;grid-template-columns:52px minmax(0,1fr);gap:11px;align-items:center;padding:13px;border:1px solid #3b5053;border-radius:9px;background:#102126}.transfer-result-player.is-in{border-color:#6f9f58;background:#172f26}.transfer-result-player.is-out{border-color:#94574f;background:#2b2021}.transfer-result-icon{grid-row:1/3;display:grid;place-items:center;width:44px;height:44px;border-radius:50%;font-size:25px;background:#0c191b}.transfer-result-player.is-in .transfer-result-icon{background:#294b34}.transfer-result-player.is-out .transfer-result-icon{background:#492a2a}.transfer-result-name{display:flex;align-items:center;gap:8px;min-width:0}.transfer-result-name b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px}.transfer-result-meta{display:block;margin-top:4px;color:#9fb1ae;font-size:10px}.transfer-result-status{grid-column:2;margin:2px 0 0;font-size:11px;font-weight:700}.transfer-result-player.is-in .transfer-result-status{color:#b9ef9c}.transfer-result-player.is-out .transfer-result-status{color:#ffada4}.transfer-result-card>.primary{margin-top:4px}.v28-market-scroll{grid-template-columns:repeat(3,minmax(0,1fr))!important;grid-auto-rows:1fr;max-height:330px;overflow-y:auto;overscroll-behavior:contain;padding:2px 7px 7px 2px;scrollbar-color:var(--club-primary) #102126;scrollbar-width:thin}.v28-market-scroll .market-card{min-height:305px}.v28-market-scroll::-webkit-scrollbar{width:8px}.v28-market-scroll::-webkit-scrollbar-track{background:#102126;border-radius:8px}.v28-market-scroll::-webkit-scrollbar-thumb{background:var(--club-primary);border-radius:8px}
@media(max-width:760px){.v28-market-scroll{grid-template-columns:1fr!important;grid-auto-rows:auto;max-height:700px}.v28-market-scroll .market-card{min-height:215px}}
@media(max-width:600px){.transfer-result-modal{padding:10px}.transfer-result-card{padding:17px;max-height:calc(100vh - 20px)}.transfer-result-head h2{font-size:27px}}
`;
document.head.append(v28TransferStyle);

function v28TransferResultData(state,pending){return pending.map(item=>{const bid=state.bids.find(entry=>entry.id===item.bidId),offer=state.offers.find(entry=>entry.id===item.offerId),player=offer?.player||item.player,status=bid?.status||'rejected',inTeam=status==='accepted',nation=typeof nationData!=='undefined'?(nationData[player?.nation]?.name||player?.nation||'Unbekannt'):(player?.nation||'Unbekannt');return{bidId:item.bidId,name:player?.name||bid?.playerName||'Unbekannter Spieler',age:player?.age||'–',nationCode:player?.nation||'',nation,status,inTeam,counterAmount:bid?.counterAmount||0}})}
function v28ResultLabel(result){if(result.inTeam)return'Im Team · Transfer abgeschlossen';if(result.status==='counter')return`Noch nicht im Team · Gegenangebot ${result.counterAmount} Credits`;if(result.status==='lost')return'Nicht im Team · Spieler nicht mehr verfügbar';return'Nicht im Team · Angebot abgelehnt'}
function v28ShowTransferResults(results,day){
 document.querySelector('#transfer-result-modal')?.remove();if(!results.length)return;
 const modal=document.createElement('div');modal.id='transfer-result-modal';modal.className='transfer-result-modal';modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.setAttribute('aria-labelledby','transfer-result-title');modal.innerHTML=`<section class="transfer-result-card"><header class="transfer-result-head"><div><p class="eyebrow">TRANSFERTAG ${day}</p><h2 id="transfer-result-title">Transferentscheidungen</h2></div><button class="transfer-result-close" aria-label="Fenster schließen">×</button></header><div class="transfer-result-list">${results.map(result=>`<article class="transfer-result-player ${result.inTeam?'is-in':'is-out'}"><span class="transfer-result-icon" aria-hidden="true">${result.inTeam?'👍':'👎'}</span><div class="transfer-result-name">${result.nationCode?flagSVG(result.nationCode):''}<b>${escapeHTML(result.name)}</b></div><span class="transfer-result-meta">${escapeHTML(String(result.age))} Jahre · ${escapeHTML(result.nation)}</span><p class="transfer-result-status">${escapeHTML(v28ResultLabel(result))}</p></article>`).join('')}</div><button class="primary transfer-result-ok">Weiter zum Transfertag <span>↗</span></button></section>`;document.body.append(modal);
 const close=()=>modal.remove();modal.querySelector('.transfer-result-close').onclick=close;modal.querySelector('.transfer-result-ok').onclick=close;modal.onclick=event=>{if(event.target===modal)close()};modal.querySelector('.transfer-result-close').focus()
}
function v28ScrollableMarkets(){clubCenter.querySelectorAll('.qol-market > .market-grid').forEach(grid=>{grid.classList.add('v28-market-scroll');grid.setAttribute('role','region');grid.setAttribute('tabindex','0');grid.setAttribute('aria-label',grid.previousElementSibling?.textContent?.trim()||'Transferliste')})}

const v27AdvanceTransferDayV28=advanceTransferDay;
advanceTransferDay=function(){
 const state=transferState(),pending=state.bids.filter(bid=>bid.status==='pending'&&bid.resolveDay<=state.day+1).map(bid=>{const offer=state.offers.find(item=>item.id===bid.offerId);return{bidId:bid.id,offerId:bid.offerId,player:offer?.player?structuredClone(offer.player):{name:bid.playerName}}}),result=v27AdvanceTransferDayV28();
 if(result!==false&&pending.length)v28ShowTransferResults(v28TransferResultData(state,pending),state.day);return result
};

const v27RenderCenterV28=renderCenter;
renderCenter=function(){const result=v27RenderCenterV28();v28ScrollableMarkets();document.querySelectorAll('footer span:first-child').forEach(element=>element.textContent='Doppel 6 / PROTOTYP 39');return result};

drawSlots();document.querySelectorAll('footer span:first-child').forEach(element=>element.textContent='Doppel 6 / PROTOTYP 39');
